package ama.api;
import ama.access.*;import ama.meeting.*;import ama.storage.*;import ama.task.*;import ama.transcript.*;import ama.db.TransactionRunner;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;
import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import org.springframework.context.support.StaticApplicationContext;import org.springframework.beans.factory.support.DefaultListableBeanFactory;import com.fasterxml.jackson.databind.ObjectMapper;
/** Genuine current daily factory/read qualification; never creates business or result SQL fixtures. */
public final class LocalAcquisitionBudgetCheck {
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;final AtomicInteger bodies=new AtomicInteger(),metadata=new AtomicInteger();Source(DataSource delegate){this.delegate=delegate;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> type,InvocationHandler handler){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},handler);}
  private static final String BODY="(?:`?[A-Za-z_][A-Za-z_0-9]*`?\\s*\\.\\s*)?`?body`?";
  private static final java.util.regex.Pattern FROM=java.util.regex.Pattern.compile("(?i)\\bFROM\\s+(?:`?\\w+`?\\.)?`?minutes_revision`?(?=\\s|$)");
  private static final java.util.regex.Pattern UNITS=java.util.regex.Pattern.compile("(?i)OCTET_LENGTH\\s*\\(\\s*CONVERT\\s*\\(\\s*"+BODY+"\\s+USING\\s+utf16\\s*\\)\\s*\\)");
  private static final java.util.regex.Pattern LENGTH=java.util.regex.Pattern.compile("(?i)(?:OCTET_LENGTH|CHAR_LENGTH)\\s*\\(\\s*"+BODY+"\\s*\\)");
  static String projection(String sql){var from=FROM.matcher(sql);return from.find()?sql.substring(0,from.start()):null;}
  static boolean rawBody(String projection){
   // Remove only known scalar measurements. Mixed raw columns still count, regardless of length columns.
   String remaining=LENGTH.matcher(UNITS.matcher(projection).replaceAll("0")).replaceAll("0").replaceAll("(?i)COUNT\\s*\\(\\s*\\*\\s*\\)","0");
   return java.util.regex.Pattern.compile("(?i)\\bbody\\b").matcher(remaining).find()||remaining.contains("*");
  }
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object r=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&r instanceof PreparedStatement statement)return proxy(statement,PreparedStatement.class,(s,sm,sa)->{
    // Observe before executeQuery because Connector/J may buffer the entire result at execution.
    if(sm.getName().equals("executeQuery")){String selected=projection(sql);if(selected!=null){if(rawBody(selected)){check(!actual.getAutoCommit(),"Body transfer requires the actual held transaction");bodies.incrementAndGet();}if(sql.toUpperCase(java.util.Locale.ROOT).contains("OCTET_LENGTH("))metadata.incrementAndGet();}}
    return invoke(statement,sm,sa);
   });return r;});}
  void reset(){bodies.set(0);metadata.set(0);}public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 record Built(ProcessingConfiguration.Runtime processing,TranscriptConfiguration.Runtime transcript,MinutesConfiguration.Runtime minutes,TransactionRunner tx,JdbcMeetingAccess access,JdbcSubjectFences fences,JdbcOutbox outbox,JdbcTaskQueue queue){}
 static Built build(DataSource source,StandardEnvironment env,FileBackendCatalog catalog,ControlledKnowledgeClient client){var tx=new TransactionRunner(source,30);var fences=new JdbcSubjectFences(source,Set.of("MEETING"));var access=new JdbcMeetingAccess(source,tx,fences);var refs=new HashMap<String,OutboxReferenceValidator>(new MeetingEventReferences(source).validators());refs.putAll(new TranscriptEventReferences(source).validators());refs.putAll(new MinutesEventReferences(source).validators());var outbox=new JdbcOutbox(source,refs);var factory=new ProcessingConfiguration();var processing=factory.processingRuntime(source,tx,access,new TranscriptFilePurposePolicy(),catalog,Map.of(),env);check(processing.components()!=null,"Genuine processing required");var queue=factory.processingQueue(source,fences,outbox,processing);TranscriptConfiguration.Runtime transcript;try(var context=new StaticApplicationContext()){transcript=TranscriptConfiguration.assemble(processing,source,fences,outbox,env,context);}var beans=new DefaultListableBeanFactory();beans.registerSingleton("qualificationKnowledge",client);var minutes=new MinutesConfiguration().minutesRuntime(processing,transcript,env,queue,outbox,source,beans.getBeanProvider(ControlledKnowledgeClient.class));minutes.requireCombined();return new Built(processing,transcript,minutes,tx,access,fences,outbox,queue);}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==2,"Explicit daily qualification required");Path configuration=Path.of(args[0]).toRealPath();check(configuration.getParent().endsWith(Path.of(".tools/local-app"))&&Files.size(configuration)<65536,"Daily configuration required");var properties=new Properties();try(var in=Files.newInputStream(configuration)){properties.load(in);}String url=properties.getProperty("database.url");check(url!=null&&url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");String meeting=args[1];UUID.fromString(meeting);var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",properties));var source=new Source(ControlledMinutesDataSource.create(url,properties.getProperty("database.user"),properties.getProperty("database.password")));var j=new JdbcTemplate(source);j.setQueryTimeout(5);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));var original=LocalActionOwnerCheck.snapshot(j,meeting);
  var configured=ConfiguredProcessing.read(env);var settings=ConfiguredMinutes.read(env,configured.read(),configured.index());try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=build(source,env,catalog,client);var physical=LocalRowBudgetCheck.verify(runtime.processing().components().authority(),actor,meeting,settings,source::reset,source.bodies::get,source.metadata::get);
   source.reset();runtime.tx().required(()->{try{runtime.minutes().saved().current(actor,meeting);throw new AssertionError("Ambient read must reject");}catch(IllegalStateException expected){check(expected.getMessage().contains("ambient transaction"),"Actual ambient-transaction guard required");}return null;});check(source.bodies.get()==0,"Ambient read must not transfer body");
   var small=new ArrayList<Map<String,Object>>();for(String name:List.of("utf8","scalars","utf16","copy-bytes","copy-utf16","response-bytes")){
    env.getPropertySources().addFirst(new MapPropertySource("tiny",Map.of("minutes.bounds."+name,"1")));try{var tiny=build(source,env,catalog,client);source.reset();try{tiny.minutes().saved().current(actor,meeting);throw new AssertionError("Tiny full query must reject");}catch(ama.contract.MinutesContracts.Failure failed){check(failed.code()==ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,"Actual full query budget rejection required");}check(source.bodies.get()==0,"Tiny complete query must reject before body transfer");small.add(Map.of("dimension",name,"bodyQueries",source.bodies.get(),"outcome","BUDGET_EXCEEDED"));}finally{env.getPropertySources().remove("tiny");}
   }
   check(original.equals(LocalActionOwnerCheck.snapshot(j,meeting)),"Budget qualification must not change business state");System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",true,"meetingId",meeting,"genuineFactories",true,"physical",physical,"fullQueryTiny",small,"ambientTransactionRejectedBeforeBody",true,"zeroBusinessEffects",true)));
  }
 }
}
